#!/usr/bin/env node
/**
 * Builds the MCP App view into one self-contained HTML document, then writes it out
 * as a TypeScript module the MCP server imports.
 *
 * Self-contained because a host renders the view in a sandboxed iframe with no
 * network access by default: everything — script, styles — has to be inside the
 * resource itself. And a generated module rather than a file read at runtime, so the
 * Lambda bundle carries the view with it and there is nothing to deploy alongside.
 *
 * The generated file is gitignored. `npm run check` and `npm run build:lambda` run
 * this first.
 */
import { build } from 'esbuild';
import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');

const bundle = await build({
  entryPoints: [join(root, 'mcp-app', 'main.ts')],
  bundle: true,
  write: false,
  format: 'esm',
  platform: 'browser',
  target: 'es2022',
  minify: true,
  legalComments: 'none',
  logLevel: 'warning',
  plugins: [
    {
      // The ext-apps client validates messages with Zod, and Zod's barrel re-exports
      // error messages in about fifty languages — roughly 300 KiB of a 520 KiB view.
      // Only the English locale is ever used (Zod imports it directly), so the barrel
      // is replaced with an empty module. Validation itself is untouched.
      name: 'drop-zod-locale-barrel',
      setup(b) {
        b.onResolve({ filter: /^\.\.\/locales\/index\.js$/ }, (args) =>
          /[\\/]zod[\\/]/.test(args.importer) ? { path: 'zod-locales', namespace: 'stub' } : undefined,
        );
        b.onLoad({ filter: /.*/, namespace: 'stub' }, () => ({ contents: 'export {};', loader: 'js' }));
      },
    },
  ],
});

const script = bundle.outputFiles[0].text
  // An inline script ends at the first "</script", wherever it appears.
  .replace(/<\/script/gi, '<\\/script');

const template = await readFile(join(root, 'mcp-app', 'today.html'), 'utf8');
if (!template.includes('/*__APP_SCRIPT__*/')) throw new Error('today.html is missing the script placeholder');
const html = template.replace('/*__APP_SCRIPT__*/', () => script);

const out = join(root, 'src', 'mcp', 'app-html.generated.ts');
await writeFile(
  out,
  [
    '// Generated by scripts/build-mcp-app.mjs from mcp-app/. Do not edit.',
    `export const APP_HTML = ${JSON.stringify(html)};`,
    '',
  ].join('\n'),
);

console.log(`MCP App view: ${(html.length / 1024).toFixed(1)} KiB → src/mcp/app-html.generated.ts`);
